  ('00000021-0000-4000-8000-000000000006', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Marketing Agency Retainer', 'IN FLIGHT. Not yet signed, so this reports as FORECAST rather than booked savings on the dashboard.', 'Renewal', '000000c1-0000-4000-8000-000000000005', '000000b1-0000-4000-8000-000000000003', '00000051-0000-4000-8000-000000000005', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Negotiation', 'USD', 1, '2026-09-01', '2026-09-01', '2027-08-31', 'Sourcing', 'Sample Buyer', null, now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000021-0000-4000-8000-000000000007', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Network Infrastructure - 5 Year', 'A FIVE-YEAR term with the annual escalator priced into the offer totals, which is why a single amount plus a term stays exact.', 'Renewal', '000000c1-0000-4000-8000-000000000001', '000000b1-0000-4000-8000-000000000001', '00000051-0000-4000-8000-000000000008', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Contracted', 'USD', 1, '2026-04-01', '2026-04-01', '2031-03-31', 'Sourcing', 'Sample Buyer', null, now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
